const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','sync.js','smart-sync.js','deck-midi.js','midi.js','panels.js','tempo-slider.js','fx-tempo-capture-worklet.js','simple-sync-controller-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
const click=s=>{assert($(s),'Missing '+s);$(s).click();},value=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);},button=(i,a)=>`[data-deck="${i}"][data-action="${a}"]`;
async function until(fn,label){const deadline=performance.now()+15000;while(!fn()){assert(performance.now()<deadline,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
function metrics(data,sr){let energy=0,peak=0,finite=true;const crossings=[];for(let i=0;i<data.length;i++){const x=data[i];finite&&=Number.isFinite(x);energy+=x*x;peak=Math.max(peak,Math.abs(x));if(i&&data[i-1]<0&&x>=0)crossings.push(i-1-data[i-1]/(x-data[i-1]));}return{frames:data.length,finite,rms:Math.sqrt(energy/data.length),peak,hz:crossings.length>1?(crossings.length-1)*sr/(crossings.at(-1)-crossings[0]):null};}
let app;
const before=new URL(location.href).searchParams.has('before');
async function run(){const {state,engine}=app;$('#simple-controller-run').disabled=true;const r={startedAt:new Date().toISOString(),completed:false,scope:'Actual production browser Simple Sync GUI-handler and synthetic MIDI-editor inputs, generated engine buffers, post-master stereo Float32 and whole recording. Internal MIDI-controller route only. Not physical hardware, native, DVS/CDJ modes, file import, musical quality, exact vendor taper or full Sync parity',criteria:{settleSeconds:.3,captureSeconds:.3,frequencyToleranceHz:.3,minimumRMS:.005,silencePeak:.000001},cases:[],errors:[]};let witnesses=[];
 function output(){const safe={...r,cases:r.cases.map(c=>({...c,pcm:c.pcm?.map(p=>({...p,base64:'Retained in private original'}))})),recording:r.recording?{...r.recording,base64:'Retained in private original'}:undefined};$('#simple-controller-results').textContent=JSON.stringify(safe,null,2);$('#simple-controller-original').textContent=JSON.stringify(r,null,2);}
 const midiOpen=()=>click('[data-panel="midi"]');
 function packet(type,channel,number,v){value('#midi-type',type);value('#midi-channel',channel);value('#midi-number',number);value('#midi-test-value',v);click('#midi-send');}
 function fader(raw,ignore=false){midiOpen();packet('CC',ignore?6:3,8,raw>>7);packet('CC',ignore?6:3,40,raw&127);click('#modal-close');}
 async function sample(name,rates,action=()=>{},{silence=false}={}){const c={name,expectedRates:rates,expectedFrequencies:rates.map((v,i)=>silence?0:(i?550:330)*v)};r.cases.push(c);$('#simple-controller-status').textContent='Running '+name;await action();await until(()=>state.decks.slice(0,2).every(d=>!d.processing),'Transport preparation');await sleep(300);
  c.rates=state.decks.slice(0,2).map(d=>d.rate);c.sync=state.decks.slice(0,2).map(d=>({sync:d.sync,state:d.syncState,position:engine.position(d),playing:d.playing}));
  const id=r.cases.length,raw=await Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM capture timeout')),5000);w.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate*.3)});})));c.pcm=[];c.measured=[];
  for(let i=0;i<2;i++){const bytes=new Uint8Array(raw[i].data.buffer);c.pcm.push({startFrame:raw[i].startFrame,frames:raw[i].data.length,sha256:await hash(bytes),base64:base64(bytes)});c.measured.push(metrics(raw[i].data,engine.ctx.sampleRate));}
  c.passed=c.measured.every((m,i)=>m.finite&&(c.expectedFrequencies[i]===0?m.peak<r.criteria.silencePeak:m.rms>=r.criteria.minimumRMS&&Math.abs(m.hz-c.expectedFrequencies[i])<=r.criteria.frequencyToleranceHz));c.rateMatches=c.rates.every((v,i)=>Math.abs(v-rates[i])<1e-8);c.passed&&=c.rateMatches;output();}
 try{r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical graph must be muted');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],[120,100],state.fxTempo);
  await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);for(let i=0;i<2;i++){const w=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,i);w.connect(engine.ctx.destination);witnesses.push(w);}r.sampleRate=engine.ctx.sampleRate;
  for(let i=0;i<2;i++){const d=state.decks[i],b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*60,engine.ctx.sampleRate);for(let n=0;n<b.length;n++)b.getChannelData(i)[n]=.05*Math.sin(2*Math.PI*(i?550:330)*n/b.sampleRate);Object.assign(d.track,{bpm:i?100:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration:60,analyzed:true});Object.assign(d,{rate:1,position:0,pitchRange:8,keylock:false,keyShift:0,reverse:false,loop:false,sync:false,syncState:'off'});engine.clearDeckScratchCache(i);engine.buffers.set(d.track.id,b);engine.mix(i,'level',.8);}
  click('[data-panel="settings"]');value('[data-setting="Sync Mode"]','Simple Sync');$('[data-setting="Sync Mode"]').dispatchEvent(new Event('change',{bubbles:true}));$('[data-setting="Snap to Beatgrid"]').checked=true;$('[data-setting="Snap to Beatgrid"]').dispatchEvent(new Event('change',{bubbles:true}));click('#save-settings');midiOpen();click('#midi-reset');
  for(const[target,type,channel,number,encoding]of[['Deck 2 tempo','CC',3,8,'14-bit absolute'],['Deck 2 tempo ignore','CC',6,8,'14-bit absolute'],['Deck 2 sync','Note',8,12,'7-bit absolute'],['Deck 2 sync off','Note',8,13,'7-bit absolute'],['Deck 1 tempo','CC',2,8,'14-bit absolute']]){value('#midi-target',target);value('#midi-type',type);value('#midi-channel',channel);value('#midi-number',number);value('#midi-encoding',encoding);click('#midi-add');}click('#modal-close');
  const note=n=>{midiOpen();packet('Note',8,n,127);packet('Note',8,n,0);click('#modal-close');};
  fader(8192);fader(6144);await until(()=>Math.abs(state.decks[1].rate-.98)<1e-8,'Initial received -2percent pitch');
  click(button(0,'play'));await until(()=>state.decks[0].playing,'Primary playback');click(button(1,'sync'));await until(()=>state.decks[1].sync&&Math.abs(state.decks[1].rate-1.2)<1e-8,'Simple Sync tempo');click(button(1,'play'));await until(()=>state.decks[1].playing&&!state.decks[1].processing,'Secondary playback');await engine.recordStart();
  await sample('Simple Sync +20percent preserves the cached -2percent controller coordinate',[1,1.2],()=>fader(6144));
  await sample('Controller movement changes shared Simple Sync tempo beyond its absolute range',[1.21/1.2,1.21],()=>fader(7168));
  await sample('One GUI OFF restores cached -1percent and leaves primary tempo unchanged',[1.21/1.2,.99],()=>click(button(1,'syncOff')));
  if(!before){
   await sample('Unsynced controller fader resumes ordinary absolute pitch',[1.21/1.2,.98],()=>fader(6144));
   await sample('Synthetic MIDI Sync re-engages shared Simple Sync',[1.21/1.2,1.21],async()=>{note(12);await until(()=>state.decks[1].sync&&!state.decks[1].processing,'MIDI Simple Sync');});
   await sample('GUI primary tempo then controller movement rebases relative pitch',[1.2312/1.2,1.2312],async()=>{const input=$('[data-tempo="0"]');input.value=String(Number(input.value)+.1);input.dispatchEvent(new Event('input',{bubbles:true}));await until(()=>Math.abs(state.decks[1].rate-1.2112)<1e-8,'Shared GUI tempo');fader(8192);});
   await sample('Mapped Shift-ignore and release leave Simple Sync tempo unchanged',[1.2312/1.2,1.2312],()=>{fader(4096,true);fader(4096);});
   await sample('Controller movement resumes after Shift reposition',[1.2412/1.2,1.2412],()=>fader(5120));
   await sample('Synthetic MIDI OFF restores cached -3percent immediately',[1.2412/1.2,.97],()=>note(13));
   await sample('Unknown primary controller position is preserved until first actual packet',[1,.97],async()=>{click(button(0,'syncOff'));await until(()=>!state.decks[0].sync,'Primary OFF');await sleep(20);r.unknownPositionAfterOFF={rate:state.decks[0].rate,sync:state.decks[0].sync,state:state.decks[0].syncState};midiOpen();packet('CC',2,8,64);packet('CC',2,40,0);click('#modal-close');});
  }
  await sample('Both normal Play controls stop the master',before?[1.21/1.2,.99]:[1,.97],async()=>{click(button(0,'play'));click(button(1,'play'));await until(()=>!state.decks[0].playing&&!state.decks[1].playing,'Stop');},{silence:true});
 }catch(error){r.errors.push({message:error.message,stack:error.stack});}
 finally{for(const d of state.decks)engine.pause(d);if(engine.recording){const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer()),b=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));let finite=true;for(let c=0;c<b.numberOfChannels;c++)for(const x of b.getChannelData(c))finite&&=Number.isFinite(x);r.recording={bytes:bytes.length,sha256:await hash(bytes),base64:base64(bytes),format:blob.type,sampleRate:b.sampleRate,frames:b.length,channels:b.numberOfChannels,allFinite:finite};}for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.completed=r.cases.length===(before?4:11)&&r.cases.every(c=>c.passed)&&!r.errors.length&&r.sourceStable&&r.recording?.allFinite;r.finishedAt=new Date().toISOString();output();const link=$('#simple-controller-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));link.download='simple-sync-controller-original.json';link.hidden=false;$('#simple-controller-status').textContent=r.completed?'Scoped controller simple-controller-tempo workflow passed; stopped':'Scoped failures captured: '+r.cases.filter(c=>!c.passed).map(c=>c.name).join('; ')+r.errors.map(e=>e.message).join('; ');}
}
$('#simple-controller-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#simple-controller-run').disabled=false;$('#simple-controller-status').textContent='Ready';}boot().catch(error=>$('#simple-controller-status').textContent=error.message);
